using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Contracts.Accounting.Settings;using OAS.Domain.Accounting.Entities;using ContractRateType=OAS.Contracts.Accounting.Enums.ExchangeRateType;
namespace OAS.Application.Accounting.Settings.Queries.GetAccountingSettings;public sealed class GetAccountingSettingsQueryHandler(IReadRepository<AccountingSettings,Guid> repository,IReadRepository<Currency,Guid> currencies):IRequestHandler<GetAccountingSettingsQuery,AccountingSettingsDto?>{public async Task<AccountingSettingsDto?> Handle(GetAccountingSettingsQuery r,CancellationToken ct){var e=await repository.GetByIdAsync(AccountingSettings.SingletonId,ct);if(e is null)return null;var c=await currencies.GetByIdAsync(e.BaseCurrencyId,ct);return new(e.Id,e.BaseCurrencyId,c?.Code??string.Empty,e.EmployeeParentAccountId,e.CashParentAccountId,e.BankParentAccountId,e.ExchangeGainAccountId,e.ExchangeLossAccountId,(ContractRateType)(byte)e.DefaultExchangeRateType,Convert.ToBase64String(e.RowVersion));}}
